<?php
namespace App\Http\Controllers;
use App\Modules\Operations\Models\Shift; use App\Modules\Tasks\Models\{Checklist,ChecklistItem,Task}; use Illuminate\Http\Request;
class TasksController extends Controller { public function tasks(){return view('tenant.tasks.tasks',['tasks'=>Task::orderBy('name')->get()]);} public function storeTask(Request $r){Task::create($r->validate(['name'=>'required|max:150','description'=>'nullable','status'=>'required|in:active,inactive']));return back();} public function checklists(){return view('tenant.tasks.checklists',['checklists'=>Checklist::with('items.task','shift')->get(),'tasks'=>Task::where('status','active')->get(),'shifts'=>Shift::where('status','active')->get()]);} public function storeChecklist(Request $r){Checklist::create($r->validate(['name'=>'required|max:150','shift_id'=>'required|exists:tenant.shifts,id','status'=>'required|in:active,inactive']));return back();} public function storeItem(Request $r, Checklist $checklist){$d=$r->validate(['task_id'=>'required|exists:tenant.tasks,id','sort_order'=>'required|integer|min:1','start_time'=>'nullable','due_time'=>'nullable']);$d['checklist_id']=$checklist->id;ChecklistItem::create($d);return back();} }
